# ============================================================
# TrustLens — plain-language chart summaries (LLM explainer)
# ============================================================
#
# Scope §6.9: "Every chart is accompanied by a plain-language summary
# generated by the LLM explainer module."
#
# Same rule as the browser extension's explain.py: the language model only
# WORDS numbers it is handed; it never decides a score or a verdict. It gets
# this scan's numbers and nothing else, and is asked for one or two sentences
# per chart. If Gemini isn't configured, is down, or returns something
# unusable, every chart gets a rule-based sentence built from the same
# numbers instead, and the page says which of the two wrote it.

import json
import os

import requests
from dotenv import dotenv_values

_GATEWAY_ENV = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "browser_extension", "gateway", ".env")
GEMINI_ENDPOINT = "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"


def _gemini_settings():
    key = os.getenv("GEMINI_API_KEY", "").strip()
    model = os.getenv("GEMINI_MODEL", "").strip()
    if not key and os.path.exists(_GATEWAY_ENV):     # the key the extension already uses
        env = dotenv_values(_GATEWAY_ENV)
        key = (env.get("GEMINI_API_KEY") or "").strip()
        model = model or (env.get("GEMINI_MODEL") or "").strip()
    return key, model or "gemini-2.5-flash"


NICE = {"fake_follower": "account authenticity", "engagement": "engagement",
        "misinformation": "misinformation", "credential": "credentials"}


def not_applied(result):
    """Each check that didn't run, with the plain reason, so the summary can
    say "no qualification was claimed" instead of "a score is missing"."""
    ms = (result.get("trust_score") or {}).get("module_scores") or {}
    out = {}
    if "credential" not in ms:
        claims = (result.get("credential_analysis") or {}).get("claims_found") or []
        out["credentials"] = (f"the bio claims {', '.join(claims)} but no public register exists to check it"
                              if claims else "the bio doesn't claim any qualification")
    if "misinformation" not in ms:
        out["misinformation"] = "there was no bio or caption text to read"
    if "engagement" not in ms:
        out["engagement"] = "Instagram returned no posts to measure"
    return out


def chart_facts(result, timeline=None):
    ff = result.get("fake_follower_analysis") or {}
    eng = result.get("engagement_analysis") or {}
    ts = result.get("trust_score") or {}
    posts = (result.get("engagement_data") or {}).get("posts") or []
    facts = {
        # Only what the four charts show. The overall score, verdict and
        # confidence are left out on purpose, so no chart text can restate
        # (or garble) the verdict: the page's headline already says it.
        "username": result.get("username"),
        "fake_account_likelihood_pct": ff.get("bot_percentage"),
        "check_scores_0_to_100": {NICE[m]: v for m, v in (ts.get("module_scores") or {}).items()},
        "check_weights_pct": {NICE[m]: v for m, v in (ts.get("weights_used") or {}).items()},
        "checks_that_did_not_apply": not_applied(result),
        "engagement_rate_pct": eng.get("engagement_rate"),
        "engagement_benchmark_pct_for_this_size": eng.get("benchmark"),
        "size_tier": eng.get("tier"),
        "likes_per_post_oldest_to_newest": [p.get("likes") for p in reversed(posts)],
        "comments_per_post_oldest_to_newest": [p.get("comments") for p in reversed(posts)],
        "comments_turned_off_by_the_creator": bool(eng.get("comments_off")),
    }
    if timeline:
        facts["follower_timeline"] = [{"date": p["date"], "followers": p["followers"]}
                                      for p in timeline.get("points", [])]
        facts["follower_jumps_over_10pct"] = timeline.get("anomalies")
    return facts


# --------------------------------------------------------------------------- #
# Rule-based fallback
# --------------------------------------------------------------------------- #
LABEL = {"fake_follower": "account authenticity", "engagement": "engagement",
         "misinformation": "misinformation", "credential": "credentials"}


def rule_summaries(result, timeline=None):
    f = chart_facts(result, timeline)
    out = {}
    bot = f["fake_account_likelihood_pct"]
    if bot is not None:
        side = ("looks like a genuine account" if bot < 40 else
                "is borderline" if bot < 70 else "looks like a fake or spam account")
        out["gauge"] = f"The fake-account model puts this account at {bot}%, so it {side} (the needle's red zone starts at 70%)."
    ms = (result.get("trust_score") or {}).get("module_scores") or {}
    if ms:
        hi = max(ms, key=ms.get)
        lo = min(ms, key=ms.get)
        out["radar"] = (f"Strongest check: {LABEL[hi]} ({ms[hi]:.0f}/100). Weakest: {LABEL[lo]} ({ms[lo]:.0f}/100)."
                        if hi != lo else f"Only {LABEL[hi]} applied, at {ms[hi]:.0f}/100.")
        for check, why in not_applied(result).items():
            out["radar"] += f" {check.capitalize()} didn't apply: {why}."
    likes = [x for x in f["likes_per_post_oldest_to_newest"] if x is not None]
    if len(likes) >= 3:
        first, last = sum(likes[:3]) / 3, sum(likes[-3:]) / 3
        trend = ("rising" if last > first * 1.2 else "falling" if last < first * 0.8 else "fairly flat")
        med = sorted(likes)[len(likes) // 2] or 1
        spikes = sum(1 for x in likes if x > 3 * med)
        out["trend"] = (f"Likes across the last {len(likes)} posts are {trend}"
                        + (f", with {spikes} post(s) over 3x the usual" if spikes else "") + ".")
        if f["engagement_rate_pct"] is not None:
            out["trend"] += (f" Overall engagement is {f['engagement_rate_pct']}% against about "
                             f"{f['engagement_benchmark_pct_for_this_size']}% typical for {f['size_tier']} accounts.")
    pts = (timeline or {}).get("points") or []
    if len(pts) >= 2:
        a, b = pts[0], pts[-1]
        ch = (b["followers"] - a["followers"]) / a["followers"] * 100 if a["followers"] else 0
        out["timeline"] = (f"From {a['date']} to {b['date']} followers went from {a['followers']:,} to "
                           f"{b['followers']:,} ({ch:+.1f}%).")
        if (timeline or {}).get("anomalies"):
            out["timeline"] += f" {len(timeline['anomalies'])} sudden jump(s) of 10%+ are flagged."
    elif len(pts) == 1:
        out["timeline"] = "TrustLens has scanned this account on one day so far; the timeline fills in with later scans."
    return out


# --------------------------------------------------------------------------- #
# Gemini
# --------------------------------------------------------------------------- #
SYSTEM = """You write one or two short plain-English sentences under each chart \
on a report about an Instagram account. The numbers are final: explain them, \
never change them, never add numbers that aren't given, never give a new \
verdict. Say plainly when something is missing. No jargon, no hype, no emoji. \
Each chart's text must describe ONLY that chart's own numbers: the gauge \
talks about fake-account likelihood, the radar about the four check scores, \
the trend about likes per post, the timeline about follower counts. Don't \
mention the overall confidence or the verdict in any of them. \
Return JSON with exactly the keys you are asked for."""


def _ask_gemini(facts, keys):
    key, model = _gemini_settings()
    if not key:
        return None
    example = "{" + ", ".join(f'"{k}": "..."' for k in keys) + "}"
    prompt = ("Charts to describe: " + ", ".join(keys) + ".\n"
              "Answer with ONE flat JSON object exactly like " + example + ".\n"
              "gauge = fake-account likelihood gauge; radar = score of each check 0-100; "
              "trend = likes and comments per recent post; timeline = follower count over time.\n"
              "Numbers:\n" + json.dumps(facts, default=str))
    payload = {
        "systemInstruction": {"parts": [{"text": SYSTEM}]},
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0.2, "maxOutputTokens": 600,
                             "responseMimeType": "application/json",
                             "thinkingConfig": {"thinkingBudget": 0}},
    }
    r = requests.post(GEMINI_ENDPOINT.format(model=model), params={"key": key},
                      json=payload, timeout=20)
    r.raise_for_status()
    parts = (((r.json().get("candidates") or [{}])[0].get("content") or {}).get("parts") or [])
    return _pick_summaries(json.loads("".join(p.get("text", "") for p in parts)), keys)


def _pick_summaries(data, keys):
    """Gemini usually answers {"gauge": "...", ...} but sometimes wraps it
    ({"charts": {...}}) or returns a list ([{"chart": "gauge", "text": "..."}]).
    Accept those shapes; anything else yields nothing and the rules are used."""
    if isinstance(data, list):
        flat = {}
        for item in data:
            if isinstance(item, dict):
                name = item.get("chart") or item.get("name") or item.get("key") or item.get("id")
                text = item.get("text") or item.get("summary") or item.get("description")
                if name and text:
                    flat[str(name).lower()] = text
        data = flat
    if isinstance(data, dict) and not any(k in data for k in keys):
        inner = [v for v in data.values() if isinstance(v, (dict, list))]
        if len(inner) == 1:
            return _pick_summaries(inner[0], keys)
    if not isinstance(data, dict):
        return {}
    return {k: str(v).strip() for k, v in data.items() if k in keys and isinstance(v, str) and v.strip()}


def explain_charts(result, timeline=None):
    """Per chart: Gemini's wording when it answered for that chart, otherwise
    the rule-based sentence. `sources` says which wrote each one, so the page
    can label every summary truthfully."""
    rules = rule_summaries(result, timeline)
    keys = list(rules.keys())
    try:
        ai = _ask_gemini(chart_facts(result, timeline), keys) or {}
    except Exception as e:
        print(f"Chart explainer: Gemini failed, using rule-based text ({type(e).__name__})")
        ai = {}
    summaries = {k: ai.get(k) or rules[k] for k in keys}
    sources = {k: "gemini" if ai.get(k) else "rules" for k in keys}
    overall = "gemini" if all(v == "gemini" for v in sources.values()) else (
        "rules" if all(v == "rules" for v in sources.values()) else "mixed")
    return {"summaries": summaries, "sources": sources, "source": overall}
